INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'perfekt-sein', 'A2', 'Perfekt with sein', 'Perfekt mit sein', 'grammar', 'Form the Perfekt tense with sein for verbs of motion and change of state.', 21) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wochenende in Hamburg', '{"title":"Wochenende in Hamburg","lines":[{"speaker":"Petra","de":"Was hast du am Wochenende gemacht?","en":"What did you do on the weekend?"},{"speaker":"Jonas","de":"Ich bin nach Hamburg gefahren.","en":"I went to Hamburg."},{"speaker":"Petra","de":"Wie bist du dorthin gekommen?","en":"How did you get there?"},{"speaker":"Jonas","de":"Ich bin mit dem Zug gefahren und dann viel gelaufen.","en":"I went by train and then walked a lot."}],"question":"How did Jonas travel to Hamburg?","options":["By train","By car","By plane"],"answer":0}'::jsonb, 'Verbs of motion like fahren, gehen and kommen use sein as the auxiliary in the Perfekt.', 2100) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Ein Ausflug', '{"title":"Ein Ausflug","text_de":"Am Samstag ist Lena früh aufgestanden. Sie ist mit dem Fahrrad zum See gefahren und dort geschwommen. Am Abend ist sie müde nach Hause gekommen.","text_en":"On Saturday Lena got up early. She cycled to the lake and swam there. In the evening she came home tired.","question":"How did Lena get to the lake?","options":["By bike","By bus","On foot"],"answer":0}'::jsonb, 'aufstehen, fahren and kommen all take sein because they describe motion or a change of state.', 2101) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich bin gestern spät aufgestanden.","en":"I got up late yesterday.","stress":"ich bin GES-tern SPÄT AUF-ge-schtan-den","tip":"Stress falls on the separable prefix auf- in aufgestanden."}'::jsonb, 'Stress pattern: ich bin GES-tern SPÄT AUF-ge-schtan-den', 2102) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Sie ___ gestern nach Berlin gefahren.","en":"She traveled to Berlin yesterday.","options":["hat","ist","war"],"answer":1}'::jsonb, 'fahren takes sein as the Perfekt auxiliary.', 2103) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Er","ist","spät","nach","Hause","gekommen"],"answer":["Er","ist","spät","nach","Hause","gekommen"],"en":"He came home late."}'::jsonb, 'sein + past participle: ist gekommen.', 2104) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"fahren","en":"to travel/drive"},{"de":"kommen","en":"to come"},{"de":"aufstehen","en":"to get up"},{"de":"laufen","en":"to run/walk"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2105) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Wir ___ um sechs Uhr aufgewacht.","en":"We woke up at six o''clock.","options":["haben","sind","war"],"answer":1}'::jsonb, 'aufwachen describes a change of state, so it takes sein.', 2106) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks how your trip went and you want to describe your journey.","question":"What is the natural way to start?","options":["Ich bin mit dem Zug gefahren.","Ich habe mit dem Zug gefahren.","Ich fahre mit dem Zug."],"answer":0}'::jsonb, 'Motion verbs need sein in the Perfekt, not haben.', 2107) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('630a4a19-4a37-5082-a604-34cc82ebabd4'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was haben Sie letztes Wochenende gemacht? Schreiben Sie drei Sätze mit sein-Verben.', '{"prompt":"Was haben Sie letztes Wochenende gemacht? Schreiben Sie drei Sätze mit sein-Verben.","hint":"Use: Ich bin …, Dann bin ich …, Am Abend bin ich …","sample":"Ich bin am Samstag ins Kino gegangen. Dann bin ich mit Freunden spazieren gegangen. Am Abend bin ich früh eingeschlafen."}'::jsonb, 'Use the hint and compare your answer with the model.', 2108) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'praeteritum', 'A2', 'Präteritum of common verbs', 'Präteritum wichtiger Verben', 'grammar', 'Use the simple past of haben, sein and modal verbs in written and spoken German.', 22) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Als ich klein war', '{"title":"Als ich klein war","lines":[{"speaker":"Oma","de":"Als ich klein war, hatten wir kein Fernsehen.","en":"When I was young, we had no television."},{"speaker":"Tim","de":"Was habt ihr dann gemacht?","en":"What did you do then?"},{"speaker":"Oma","de":"Wir spielten draußen und lasen viel.","en":"We played outside and read a lot."}],"question":"What did grandma''s family not have?","options":["A television","A car","A garden"],"answer":0}'::jsonb, 'war and hatten are the Präteritum forms of sein and haben, common even in speech.', 2200) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meine Kindheit', '{"title":"Meine Kindheit","text_de":"Ich wuchs in einem kleinen Dorf auf. Meine Eltern hatten einen Bauernhof. Ich musste morgens früh aufstehen und half meinem Vater bei der Arbeit.","text_en":"I grew up in a small village. My parents had a farm. I had to get up early in the morning and helped my father with the work.","question":"Where did the writer grow up?","options":["In a village","In a city","Abroad"],"answer":0}'::jsonb, 'The Präteritum is common in narrative and written texts about the past.', 2201) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich hatte keine Zeit.","en":"I had no time.","stress":"ich HAT-te KEI-ne TSEIT","tip":"Double t in hatte is pronounced as one sharp t sound."}'::jsonb, 'Stress pattern: ich HAT-te KEI-ne TSEIT', 2202) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Früher ___ wir keinen Computer.","en":"In the past we had no computer.","options":["hatten","hatte","haben"],"answer":0}'::jsonb, 'wir hatten is the plural Präteritum of haben.', 2203) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Sie","konnte","sehr","gut","singen"],"answer":["Sie","konnte","sehr","gut","singen"],"en":"She could sing very well."}'::jsonb, 'Modal verbs commonly appear in the Präteritum: konnte.', 2204) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"aufwachsen","en":"to grow up"},{"de":"früher","en":"earlier/in the past"},{"de":"das Dorf","en":"the village"},{"de":"schüchtern","en":"shy"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2205) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Er ___ als Kind sehr schüchtern.","en":"He was very shy as a child.","options":["war","ist","wart"],"answer":0}'::jsonb, 'war is the Präteritum of sein for er/sie/es.', 2206) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are writing a short story about your childhood for a language class.","question":"Which tense fits best?","options":["Präteritum","Perfekt","Präsens"],"answer":0}'::jsonb, 'Written narratives about the past typically use the Präteritum.', 2207) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ddace45f-c58f-58b3-a7ed-ada5b1b7e425'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihre Kindheit. Nutzen Sie das Präteritum.', '{"prompt":"Beschreiben Sie Ihre Kindheit. Nutzen Sie das Präteritum.","hint":"Use: Ich war …, Wir hatten …, Ich musste …","sample":"Ich war als Kind sehr neugierig. Wir hatten einen Hund und einen großen Garten. Ich musste jeden Tag mein Zimmer aufräumen."}'::jsonb, 'Use the hint and compare your answer with the model.', 2208) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'dative', 'A2', 'Dative case', 'Der Dativ', 'grammar', 'Use the dative case with verbs like helfen, danken and geben.', 23) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Kannst du mir helfen?', '{"title":"Kannst du mir helfen?","lines":[{"speaker":"Nina","de":"Kannst du mir helfen?","en":"Can you help me?"},{"speaker":"Paul","de":"Klar, was brauchst du?","en":"Sure, what do you need?"},{"speaker":"Nina","de":"Ich möchte meiner Schwester ein Geschenk kaufen.","en":"I want to buy my sister a gift."},{"speaker":"Paul","de":"Gib ihr doch ein Buch.","en":"Give her a book."}],"question":"Who does Nina want to buy a gift for?","options":["Her sister","Her mother","Her friend"],"answer":0}'::jsonb, 'helfen and geben both require the dative case for the person involved.', 2300) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Ein Geschenk für den Vater', '{"title":"Ein Geschenk für den Vater","text_de":"Zum Geburtstag schenke ich meinem Vater ein neues Buch. Er dankt mir immer sehr herzlich. Ich helfe ihm auch gern im Garten.","text_en":"For his birthday I give my father a new book. He always thanks me very warmly. I also like to help him in the garden.","question":"What does the writer give the father?","options":["A book","A watch","A plant"],"answer":0}'::jsonb, 'meinem Vater and mir are dative forms after schenken and danken.', 2301) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich helfe meiner Mutter.","en":"I am helping my mother.","stress":"ich HEL-fe MEI-ner MUT-ter","tip":"meiner takes the feminine dative ending -er."}'::jsonb, 'Stress pattern: ich HEL-fe MEI-ner MUT-ter', 2302) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich gebe ___ Freund ein Buch.","en":"I am giving my friend a book.","options":["mein","meinem","meinen"],"answer":1}'::jsonb, 'der Freund is masculine, dative meinem Freund.', 2303) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Er","schenkt","seiner","Freundin","Blumen"],"answer":["Er","schenkt","seiner","Freundin","Blumen"],"en":"He gives his girlfriend flowers."}'::jsonb, 'seiner Freundin is the feminine dative form.', 2304) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"helfen","en":"to help"},{"de":"danken","en":"to thank"},{"de":"schenken","en":"to give as a gift"},{"de":"gehören","en":"to belong to"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2305) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Wir danken ___ Lehrerin.","en":"We thank the teacher.","options":["die","der","den"],"answer":1}'::jsonb, 'danken always takes the dative: der Lehrerin.', 2306) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A colleague is struggling to carry heavy boxes.","question":"What do you offer?","options":["Ich helfe dir.","Ich helfe du.","Ich helfe dich."],"answer":0}'::jsonb, 'helfen requires the dative pronoun dir, not the accusative dich.', 2307) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('08a74607-714f-5ddc-a403-fe404ca0aca1'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wem helfen Sie oft? Schreiben Sie drei Sätze mit Dativ-Verben.', '{"prompt":"Wem helfen Sie oft? Schreiben Sie drei Sätze mit Dativ-Verben.","hint":"Use: Ich helfe …, Ich danke …, Ich schenke …","sample":"Ich helfe meinem Nachbarn oft im Garten. Ich danke meinen Eltern für ihre Unterstützung. Zu Weihnachten schenke ich meiner Schwester ein Buch."}'::jsonb, 'Use the hint and compare your answer with the model.', 2308) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'two-way-prepositions', 'A2', 'Two-way prepositions', 'Wechselpräpositionen', 'grammar', 'Choose between dative and accusative with prepositions like in, auf and an.', 24) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wo stellst du die Vase hin?', '{"title":"Wo stellst du die Vase hin?","lines":[{"speaker":"Marie","de":"Wo stellst du die Vase hin?","en":"Where are you putting the vase?"},{"speaker":"Kevin","de":"Ich stelle sie auf den Tisch.","en":"I am putting it on the table."},{"speaker":"Marie","de":"Und jetzt steht sie auf dem Tisch, schön!","en":"And now it''s standing on the table, nice!"}],"question":"Where does the vase end up?","options":["On the table","Under the table","Next to the table"],"answer":0}'::jsonb, 'stellen (movement) takes accusative; stehen (position) takes dative.', 2400) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Im Klassenzimmer', '{"title":"Im Klassenzimmer","text_de":"Die Lehrerin hängt das Bild an die Wand. Jetzt hängt das Bild an der Wand. Die Schüler legen ihre Hefte auf den Tisch.","text_en":"The teacher hangs the picture on the wall. Now the picture hangs on the wall. The students put their notebooks on the table.","question":"Where does the teacher hang the picture?","options":["On the wall","On the door","On the shelf"],"answer":0}'::jsonb, 'hängen as movement (accusative) vs. hängen as position (dative).', 2401) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Das Bild hängt an der Wand.","en":"The picture hangs on the wall.","stress":"das BILD hängt an der WAND","tip":"The a in Wand is long and open."}'::jsonb, 'Stress pattern: das BILD hängt an der WAND', 2402) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich lege das Buch auf ___ Tisch.","en":"I am putting the book on the table (movement).","options":["den","dem","der"],"answer":0}'::jsonb, 'Movement/direction: auf + accusative den Tisch.', 2403) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Sie","geht","in","die","Küche"],"answer":["Sie","geht","in","die","Küche"],"en":"She is going into the kitchen."}'::jsonb, 'Direction with in takes the accusative: in die Küche.', 2404) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"stellen","en":"to put/place upright"},{"de":"legen","en":"to put/lay down"},{"de":"hängen","en":"to hang"},{"de":"die Wand","en":"the wall"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2405) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Das Buch liegt auf ___ Tisch.","en":"The book is lying on the table (position).","options":["den","dem","der"],"answer":1}'::jsonb, 'Position/location: auf + dative dem Tisch.', 2406) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You want to tell someone where you just put their keys.","question":"Which is correct if you placed them on the shelf?","options":["Ich habe die Schlüssel auf das Regal gelegt.","Ich habe die Schlüssel auf dem Regal gelegt.","Ich habe die Schlüssel auf des Regal gelegt."],"answer":0}'::jsonb, 'The action of putting something down (legen) takes the accusative.', 2407) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b6816dab-5445-54a3-a508-ef5403e5761a'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihr Zimmer mit Wechselpräpositionen.', '{"prompt":"Beschreiben Sie Ihr Zimmer mit Wechselpräpositionen.","hint":"Use: … steht in …, … liegt auf …, … hängt an …","sample":"Mein Schreibtisch steht am Fenster. Meine Bücher liegen auf dem Regal. Ein Poster hängt an der Wand."}'::jsonb, 'Use the hint and compare your answer with the model.', 2408) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'comparatives', 'A2', 'Comparatives and superlatives', 'Komparativ und Superlativ', 'grammar', 'Compare people and things using -er and am -sten forms.', 25) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Welche Stadt ist schöner?', '{"title":"Welche Stadt ist schöner?","lines":[{"speaker":"Leon","de":"Ist Berlin größer als München?","en":"Is Berlin bigger than Munich?"},{"speaker":"Sofia","de":"Ja, aber München finde ich schöner.","en":"Yes, but I find Munich more beautiful."},{"speaker":"Leon","de":"Für mich ist Hamburg am schönsten.","en":"For me, Hamburg is the most beautiful."}],"question":"Which city does Leon like best?","options":["Hamburg","Berlin","München"],"answer":0}'::jsonb, 'am schönsten is the superlative form used with sein.', 2500) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Vergleiche im Alltag', '{"title":"Vergleiche im Alltag","text_de":"Der Zug ist schneller als das Auto, aber das Fahrrad ist billiger. Am gesündesten ist es natürlich, zu Fuß zu gehen.","text_en":"The train is faster than the car, but the bike is cheaper. Of course, walking is the healthiest.","question":"What is described as the healthiest option?","options":["Walking","Cycling","The train"],"answer":0}'::jsonb, 'gesund becomes am gesündesten in the superlative, with an umlaut.', 2501) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Das ist viel besser.","en":"That is much better.","stress":"das ist FIEL BES-ser","tip":"besser is the irregular comparative of gut."}'::jsonb, 'Stress pattern: das ist FIEL BES-ser', 2502) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Mein Bruder ist ___ als ich.","en":"My brother is taller than me.","options":["groß","größer","am größten"],"answer":1}'::jsonb, 'Comparative with als: größer als.', 2503) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Dieser","Film","ist","interessanter","als","der","andere"],"answer":["Dieser","Film","ist","interessanter","als","der","andere"],"en":"This film is more interesting than the other one."}'::jsonb, 'Comparative + als introduces the comparison.', 2504) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"schnell","en":"fast"},{"de":"billig","en":"cheap"},{"de":"gesund","en":"healthy"},{"de":"am liebsten","en":"most preferably"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2505) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Das ist das ___ Restaurant der Stadt.","en":"That is the best restaurant in town.","options":["gute","bessere","beste"],"answer":2}'::jsonb, 'beste is the superlative adjective form of gut.', 2506) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks which of two cafés you prefer.","question":"How do you express a clear preference?","options":["Dieses Café ist besser.","Dieses Café ist gut.","Dieses Café ist mehr gut."],"answer":0}'::jsonb, 'besser is the comparative form used to express preference.', 2507) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('9879996d-8919-5036-a810-04295532eabd'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Vergleichen Sie zwei Städte oder Orte, die Sie kennen.', '{"prompt":"Vergleichen Sie zwei Städte oder Orte, die Sie kennen.","hint":"Use: … ist größer als …, … ist billiger, am schönsten ist …","sample":"München ist kleiner als Berlin, aber teurer. Berlin hat mehr Museen. Am schönsten finde ich aber Hamburg wegen des Hafens."}'::jsonb, 'Use the hint and compare your answer with the model.', 2508) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'subordinate-clauses', 'A2', 'Subordinate clauses with weil/dass', 'Nebensätze mit weil und dass', 'grammar', 'Give reasons and report statements with weil and dass, sending the verb to the end.', 26) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Warum lernst du Deutsch?', '{"title":"Warum lernst du Deutsch?","lines":[{"speaker":"Interviewer","de":"Warum lernst du Deutsch?","en":"Why are you learning German?"},{"speaker":"Amir","de":"Ich lerne Deutsch, weil ich in Deutschland arbeiten möchte.","en":"I am learning German because I want to work in Germany."},{"speaker":"Interviewer","de":"Denkst du, dass es schwer ist?","en":"Do you think it is difficult?"},{"speaker":"Amir","de":"Ich glaube, dass die Grammatik am schwersten ist.","en":"I believe the grammar is the hardest."}],"question":"Why does Amir learn German?","options":["To work in Germany","For a holiday","For fun"],"answer":0}'::jsonb, 'weil sends the conjugated verb to the end of the clause.', 2600) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Warum ich umziehe', '{"title":"Warum ich umziehe","text_de":"Ich ziehe um, weil meine Wohnung zu klein geworden ist. Meine Familie meint, dass ein Umzug eine gute Idee ist. Ich hoffe, dass ich bald eine neue Wohnung finde.","text_en":"I am moving because my flat has become too small. My family thinks that moving is a good idea. I hope that I find a new flat soon.","question":"Why is the writer moving?","options":["The flat is too small","The rent is too high","New job"],"answer":0}'::jsonb, 'dass also pushes the verb to the end: dass ein Umzug eine gute Idee ist.', 2601) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich denke, dass es klappt.","en":"I think it will work out.","stress":"ich DEN-ke, dass es KLAPPT","tip":"The verb klappt moves to the very end after dass."}'::jsonb, 'Stress pattern: ich DEN-ke, dass es KLAPPT', 2602) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich bin müde, weil ich zu wenig ___.","en":"I am tired because I sleep too little.","options":["schlafe","schlafen","schläft"],"answer":0}'::jsonb, 'After weil the verb goes to the end: ich schlafe.', 2603) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","bleibe","zu","Hause","weil","es","regnet"],"answer":["Ich","bleibe","zu","Hause","weil","es","regnet"],"en":"I am staying home because it is raining."}'::jsonb, 'The verb regnet goes to the very end of the weil-clause.', 2604) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"weil","en":"because"},{"de":"dass","en":"that"},{"de":"glauben","en":"to believe"},{"de":"hoffen","en":"to hope"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2605) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Sie sagt, ___ sie morgen kommt.","en":"She says that she is coming tomorrow.","options":["weil","dass","wenn"],"answer":1}'::jsonb, 'dass introduces reported statements.', 2606) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks why you cancelled your plans.","question":"Which explanation is grammatically correct?","options":["Ich kann nicht kommen, weil ich bin krank.","Ich kann nicht kommen, weil ich krank bin.","Ich kann nicht kommen, weil krank ich bin."],"answer":1}'::jsonb, 'In a weil-clause, the conjugated verb (bin) moves to the end.', 2607) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e36af98e-def8-5f50-a514-a71f1b89d28f'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Warum lernen Sie Deutsch? Erklären Sie mit weil und dass.', '{"prompt":"Warum lernen Sie Deutsch? Erklären Sie mit weil und dass.","hint":"Use: Ich lerne Deutsch, weil …, Ich denke, dass …","sample":"Ich lerne Deutsch, weil ich hier lebe und arbeite. Ich denke, dass Deutsch eine wichtige Sprache in Europa ist. Ich hoffe, dass ich bald besser sprechen kann."}'::jsonb, 'Use the hint and compare your answer with the model.', 2608) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'time-clauses', 'A2', 'Time clauses with wenn/als', 'Nebensätze mit wenn und als', 'grammar', 'Distinguish wenn for repeated or future events and als for single past events.', 27) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Als ich in Berlin ankam', '{"title":"Als ich in Berlin ankam","lines":[{"speaker":"Julia","de":"Als ich in Berlin ankam, hat es geregnet.","en":"When I arrived in Berlin, it was raining."},{"speaker":"Ben","de":"Und wenn du wieder hinfährst?","en":"And when you go there again?"},{"speaker":"Julia","de":"Wenn ich Zeit habe, besuche ich das Museum.","en":"If/when I have time, I will visit the museum."}],"question":"What happened when Julia first arrived in Berlin?","options":["It was raining","It was sunny","It was snowing"],"answer":0}'::jsonb, 'als refers to one single event in the past; wenn refers to repeated or future events.', 2700) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Kindheitserinnerungen', '{"title":"Kindheitserinnerungen","text_de":"Als ich klein war, wohnten wir am Meer. Wenn es warm war, sind wir immer schwimmen gegangen. Wenn ich heute ans Meer fahre, denke ich an meine Kindheit.","text_en":"When I was little, we lived by the sea. When it was warm, we always went swimming. When I go to the sea today, I think of my childhood.","question":"Where did the family live in the writer''s childhood?","options":["By the sea","In the mountains","In a city"],"answer":0}'::jsonb, 'als klein war = a single ongoing past situation; wenn es warm war = repeated occasions.', 2701) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Als ich ankam, war niemand da.","en":"When I arrived, nobody was there.","stress":"als ich AN-kam, war NIE-mand da","tip":"The separable verb ankommen splits: ich kam an."}'::jsonb, 'Stress pattern: als ich AN-kam, war NIE-mand da', 2702) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ ich letztes Jahr nach Spanien fuhr, war es sehr heiß.","en":"When I went to Spain last year, it was very hot.","options":["Wenn","Als","Dass"],"answer":1}'::jsonb, 'A single past event uses als, not wenn.', 2703) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wenn","es","regnet","bleibe","ich","zu","Hause"],"answer":["Wenn","es","regnet","bleibe","ich","zu","Hause"],"en":"When it rains, I stay home."}'::jsonb, 'wenn-clause first, then verb-subject order in the main clause.', 2704) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"ankommen","en":"to arrive"},{"de":"als","en":"when (single past event)"},{"de":"wenn","en":"when/if (repeated/future)"},{"de":"die Erinnerung","en":"the memory"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2705) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"___ ich Zeit habe, rufe ich dich an.","en":"When(ever) I have time, I''ll call you.","options":["Als","Wenn","Weil"],"answer":1}'::jsonb, 'wenn is used for future or repeated situations.', 2706) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are telling a friend about the one time you met a famous singer.","question":"Which word introduces this single past event?","options":["wenn","als","dass"],"answer":1}'::jsonb, 'A unique, one-time past event always uses als.', 2707) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('03de2bd5-d595-5ba6-a74d-a85e815e668e'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Erzählen Sie von einer Erinnerung mit als und einer Gewohnheit mit wenn.', '{"prompt":"Erzählen Sie von einer Erinnerung mit als und einer Gewohnheit mit wenn.","hint":"Use: Als ich …, war/hatte …, Wenn ich heute …, dann …","sample":"Als ich zehn Jahre alt war, zogen wir nach Köln um. Wenn ich heute meine alte Straße besuche, erinnere ich mich an meine Kindheit."}'::jsonb, 'Use the hint and compare your answer with the model.', 2708) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'future-werden', 'A2', 'Future with werden', 'Futur mit werden', 'grammar', 'Talk about future plans using the werden + infinitive construction.', 28) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Pläne für nächstes Jahr', '{"title":"Pläne für nächstes Jahr","lines":[{"speaker":"Sven","de":"Was wirst du nächstes Jahr machen?","en":"What will you do next year?"},{"speaker":"Amina","de":"Ich werde nach Australien reisen.","en":"I will travel to Australia."},{"speaker":"Sven","de":"Wow, wirst du dort auch arbeiten?","en":"Wow, will you also work there?"},{"speaker":"Amina","de":"Ja, ich werde in einem Café arbeiten.","en":"Yes, I will work in a café."}],"question":"What will Amina do next year?","options":["Travel to Australia","Study in Germany","Move to France"],"answer":0}'::jsonb, 'werden + infinitive expresses future plans, often with certainty or intention.', 2800) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Zukunftspläne', '{"title":"Zukunftspläne","text_de":"Nächstes Jahr werde ich meine Ausbildung beenden. Danach werde ich eine Wohnung suchen. Ich hoffe, dass ich einen guten Job finden werde.","text_en":"Next year I will finish my training. After that I will look for a flat. I hope that I will find a good job.","question":"What will the writer finish next year?","options":["Training/apprenticeship","University","A course"],"answer":0}'::jsonb, 'The infinitive (beenden, suchen) goes to the end of the sentence with werden.', 2801) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich werde morgen anrufen.","en":"I will call tomorrow.","stress":"ich WER-de MOR-gen AN-ru-fen","tip":"werde is unstressed compared to the infinitive at the end."}'::jsonb, 'Stress pattern: ich WER-de MOR-gen AN-ru-fen', 2802) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Wir ___ nächstes Jahr heiraten.","en":"We will get married next year.","options":["werden","wird","werde"],"answer":0}'::jsonb, 'wir werden is the plural form of werden.', 2803) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","werde","bald","ein","Auto","kaufen"],"answer":["Ich","werde","bald","ein","Auto","kaufen"],"en":"I will buy a car soon."}'::jsonb, 'werden in position two, infinitive kaufen at the end.', 2804) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Zukunft","en":"the future"},{"de":"die Ausbildung","en":"the training/apprenticeship"},{"de":"heiraten","en":"to get married"},{"de":"planen","en":"to plan"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2805) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Es ___ morgen regnen.","en":"It will rain tomorrow.","options":["wird","werden","werdet"],"answer":0}'::jsonb, 'es wird is the third person singular.', 2806) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks about your career plans for the future.","question":"Which sentence expresses a clear future plan?","options":["Ich werde eine neue Stelle suchen.","Ich suche eine neue Stelle gestern.","Ich habe eine neue Stelle gesucht."],"answer":0}'::jsonb, 'werden + infinitive is the clearest way to express future intentions.', 2807) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d13a4df7-37b3-5cf7-abc0-21186194d4c9'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was werden Sie in den nächsten Jahren machen? Drei Sätze mit werden.', '{"prompt":"Was werden Sie in den nächsten Jahren machen? Drei Sätze mit werden.","hint":"Use: Ich werde …, Danach werde ich …, Ich hoffe, dass ich … werde.","sample":"Ich werde nächstes Jahr meinen Deutschkurs beenden. Danach werde ich eine neue Arbeit suchen. Ich hoffe, dass ich in Deutschland bleiben werde."}'::jsonb, 'Use the hint and compare your answer with the model.', 2808) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'reflexive-verbs', 'A2', 'Reflexive verbs', 'Reflexive Verben', 'grammar', 'Use reflexive pronouns with everyday verbs like sich freuen and sich erinnern.', 29) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Ich freue mich schon', '{"title":"Ich freue mich schon","lines":[{"speaker":"Tanja","de":"Ich freue mich schon auf die Ferien.","en":"I am already looking forward to the holidays."},{"speaker":"David","de":"Ich auch! Ich muss mich aber noch erholen.","en":"Me too! But I still need to recover."},{"speaker":"Tanja","de":"Erinnerst du dich an unseren letzten Urlaub?","en":"Do you remember our last holiday?"}],"question":"What is Tanja looking forward to?","options":["The holidays","Work","The weekend"],"answer":0}'::jsonb, 'sich freuen auf takes a reflexive pronoun matching the subject.', 2900) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Morgen', '{"title":"Mein Morgen","text_de":"Ich stehe auf und dusche mich. Dann ziehe ich mich schnell an. Ich beeile mich, weil der Bus um acht Uhr fährt.","text_en":"I get up and shower. Then I get dressed quickly. I hurry because the bus leaves at eight.","question":"Why does the writer hurry?","options":["The bus leaves at eight","School starts early","It is raining"],"answer":0}'::jsonb, 'sich duschen, sich anziehen and sich beeilen are common reflexive verbs.', 2901) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich freue mich auf dich.","en":"I am looking forward to seeing you.","stress":"ich FREU-e mich auf DICH","tip":"mich is short and unstressed, the emphasis is on freue and dich."}'::jsonb, 'Stress pattern: ich FREU-e mich auf DICH', 2902) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich muss ___ beeilen.","en":"I have to hurry.","options":["mich","mir","mein"],"answer":0}'::jsonb, 'sich beeilen takes the accusative reflexive pronoun mich.', 2903) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wir","freuen","uns","auf","das","Fest"],"answer":["Wir","freuen","uns","auf","das","Fest"],"en":"We are looking forward to the party."}'::jsonb, 'The reflexive pronoun uns follows the verb directly.', 2904) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"sich freuen","en":"to be happy/look forward"},{"de":"sich erinnern","en":"to remember"},{"de":"sich beeilen","en":"to hurry"},{"de":"sich erholen","en":"to recover/relax"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2905) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Erinnerst du ___ an mich?","en":"Do you remember me?","options":["dich","dir","dein"],"answer":0}'::jsonb, 'sich erinnern an + accusative pronoun dich.', 2906) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You want to tell a friend you are excited about an upcoming trip.","question":"Which sentence is correct?","options":["Ich freue mich auf die Reise.","Ich freue auf die Reise.","Ich freue mir auf die Reise."],"answer":0}'::jsonb, 'sich freuen requires the accusative reflexive pronoun mich.', 2907) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('fb7d2ad9-85d6-56a0-a1bd-fda91ecac3c8'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihren Morgen mit reflexiven Verben.', '{"prompt":"Beschreiben Sie Ihren Morgen mit reflexiven Verben.","hint":"Use: Ich stehe auf, ich dusche mich, ich ziehe mich an, ich beeile mich.","sample":"Ich stehe um sieben Uhr auf und dusche mich sofort. Danach ziehe ich mich an und trinke einen Kaffee. Ich beeile mich, weil die Arbeit um acht beginnt."}'::jsonb, 'Use the hint and compare your answer with the model.', 2908) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'konjunktiv-politeness', 'A2', 'Konjunktiv II politeness', 'Höflichkeit mit Konjunktiv II', 'grammar', 'Make polite requests and wishes using hätte, wäre and würde.', 30) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Im Restaurant', '{"title":"Im Restaurant","lines":[{"speaker":"Kellner","de":"Was hätten Sie gern?","en":"What would you like?"},{"speaker":"Gast","de":"Ich würde gern die Suppe probieren.","en":"I would like to try the soup."},{"speaker":"Kellner","de":"Möchten Sie sonst noch etwas?","en":"Would you like anything else?"},{"speaker":"Gast","de":"Könnten Sie mir bitte auch Wasser bringen?","en":"Could you also bring me some water, please?"}],"question":"What does the guest want to try?","options":["The soup","The salad","The cake"],"answer":0}'::jsonb, 'würde + infinitive and könnten express polite requests.', 3000) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Ein höflicher Brief', '{"title":"Ein höflicher Brief","text_de":"Ich hätte gern einen Termin nächste Woche. Wäre Dienstag möglich? Ich würde mich über eine schnelle Antwort freuen.","text_en":"I would like an appointment next week. Would Tuesday be possible? I would be happy about a quick reply.","question":"What is the writer requesting?","options":["An appointment","A refund","A job"],"answer":0}'::jsonb, 'hätte gern and wäre möglich are polite Konjunktiv II forms.', 3001) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Könnten Sie mir helfen?","en":"Could you help me?","stress":"KÖNN-ten Sie mir HEL-fen","tip":"könnten has a soft ö and stresses the first syllable."}'::jsonb, 'Stress pattern: KÖNN-ten Sie mir HEL-fen', 3002) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ Sie mir bitte das Salz geben?","en":"Could you pass me the salt, please?","options":["Können","Könnten","Konnten"],"answer":1}'::jsonb, 'Könnten is the polite Konjunktiv II form of können.', 3003) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","würde","gern","einen","Tisch","reservieren"],"answer":["Ich","würde","gern","einen","Tisch","reservieren"],"en":"I would like to reserve a table."}'::jsonb, 'würde + infinitive at the end for polite requests.', 3004) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"hätte gern","en":"would like"},{"de":"könnte","en":"could"},{"de":"würde","en":"would"},{"de":"der Termin","en":"the appointment"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3005) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich ___ gern einen Kaffee.","en":"I would like a coffee.","options":["hätte","habe","hatte"],"answer":0}'::jsonb, 'Ich hätte gern is the standard polite ordering phrase.', 3006) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are calling a doctor''s office to ask for an appointment politely.","question":"Which is the most polite option?","options":["Ich will einen Termin.","Ich hätte gern einen Termin.","Gib mir einen Termin."],"answer":1}'::jsonb, 'Konjunktiv II forms like hätte gern soften requests and sound polite.', 3007) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('3ccfa974-958d-5537-a962-70125d3ae87f'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie eine höfliche Bitte an einen Vermieter oder ein Amt.', '{"prompt":"Schreiben Sie eine höfliche Bitte an einen Vermieter oder ein Amt.","hint":"Use: Ich hätte gern …, Wäre … möglich?, Ich würde mich freuen, wenn …","sample":"Ich hätte gern einen Termin für nächste Woche. Wäre Mittwochnachmittag möglich? Ich würde mich über eine kurze Antwort freuen."}'::jsonb, 'Use the hint and compare your answer with the model.', 3008) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'work-email', 'A2', 'At work and email etiquette', 'Bei der Arbeit und E-Mail-Etikette', 'work', 'Write and understand simple, polite work emails and office conversations.', 31) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Im Büro', '{"title":"Im Büro","lines":[{"speaker":"Frau Klein","de":"Guten Morgen, Herr Özdemir. Haben Sie den Bericht fertig?","en":"Good morning, Mr Özdemir. Is the report ready?"},{"speaker":"Herr Özdemir","de":"Fast. Ich schicke ihn Ihnen heute Nachmittag per E-Mail.","en":"Almost. I''ll send it to you by email this afternoon."},{"speaker":"Frau Klein","de":"Super, vielen Dank für Ihre Mühe.","en":"Great, thank you for your effort."}],"question":"When will Herr Özdemir send the report?","options":["This afternoon","Tomorrow morning","Next week"],"answer":0}'::jsonb, 'per E-Mail schicken is the standard phrase for sending something electronically.', 3100) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Eine E-Mail an den Chef', '{"title":"Eine E-Mail an den Chef","text_de":"Sehr geehrte Frau Bauer, ich möchte Ihnen mitteilen, dass ich am Freitag einen Arzttermin habe. Ich werde daher etwas später ins Büro kommen. Mit freundlichen Grüßen, Elif Yildiz.","text_en":"Dear Ms Bauer, I would like to inform you that I have a doctor''s appointment on Friday. I will therefore come to the office a bit later. Best regards, Elif Yildiz.","question":"Why will Elif come later on Friday?","options":["A doctor''s appointment","A meeting","Traffic"],"answer":0}'::jsonb, 'Sehr geehrte/r and Mit freundlichen Grüßen are formal email conventions.', 3101) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Mit freundlichen Grüßen","en":"Best regards (formal closing)","stress":"mit FREUND-li-chen GRÜ-ßen","tip":"The ß in Grüßen is pronounced like a sharp s."}'::jsonb, 'Stress pattern: mit FREUND-li-chen GRÜ-ßen', 3102) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ geehrter Herr Meier, vielen Dank für Ihre Nachricht.","en":"Dear Mr Meier, thank you for your message.","options":["Sehr","Liebe","Hallo"],"answer":0}'::jsonb, 'Sehr geehrter Herr … is the standard formal salutation.', 3103) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","melde","mich","morgen","wieder","bei","Ihnen"],"answer":["Ich","melde","mich","morgen","wieder","bei","Ihnen"],"en":"I will get back to you tomorrow."}'::jsonb, 'sich bei jemandem melden means to get in touch with someone.', 3104) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Bericht","en":"the report"},{"de":"die Nachricht","en":"the message"},{"de":"die Besprechung","en":"the meeting"},{"de":"mitteilen","en":"to inform"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3105) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich schicke Ihnen den Bericht ___ E-Mail.","en":"I am sending you the report by email.","options":["mit","per","in"],"answer":1}'::jsonb, 'per E-Mail is the fixed phrase for sending by email.', 3106) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You need to call in sick to your workplace formally.","question":"What is the most appropriate opening?","options":["Hey, ich komme heute nicht.","Sehr geehrte Frau Schulz, ich muss Ihnen leider mitteilen, dass ich heute krank bin.","Ich bin krank, tschüss."],"answer":1}'::jsonb, 'Formal work communication requires polite phrasing and a formal salutation.', 3107) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4e1968ff-4e7e-593f-ac19-2939171f27e4'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie eine kurze formelle E-Mail an Ihren Chef über einen freien Tag.', '{"prompt":"Schreiben Sie eine kurze formelle E-Mail an Ihren Chef über einen freien Tag.","hint":"Use: Sehr geehrte/r …, ich möchte Ihnen mitteilen, dass …, Mit freundlichen Grüßen.","sample":"Sehr geehrte Frau Hoffmann, ich möchte Ihnen mitteilen, dass ich am Montag einen wichtigen Termin habe. Ich werde daher einen Tag Urlaub nehmen. Mit freundlichen Grüßen, Marco Rossi."}'::jsonb, 'Use the hint and compare your answer with the model.', 3108) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'appointments-bureaucracy', 'A2', 'Appointments and bureaucracy', 'Termine und Behördengänge', 'daily-life', 'Make appointments and handle basic bureaucracy at German offices.', 32) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Beim Bürgeramt', '{"title":"Beim Bürgeramt","lines":[{"speaker":"Beamtin","de":"Guten Tag, haben Sie einen Termin?","en":"Hello, do you have an appointment?"},{"speaker":"Herr Weber","de":"Ja, um zehn Uhr, für die Anmeldung.","en":"Yes, at ten o''clock, for registration."},{"speaker":"Beamtin","de":"Haben Sie Ihren Ausweis und die Unterlagen dabei?","en":"Do you have your ID and documents with you?"},{"speaker":"Herr Weber","de":"Ja, hier bitte.","en":"Yes, here you go."}],"question":"What is Herr Weber''s appointment for?","options":["Registration","A passport","A visa"],"answer":0}'::jsonb, 'die Anmeldung is required registration when you move to a new address in Germany.', 3200) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Ein Termin beim Amt', '{"title":"Ein Termin beim Amt","text_de":"Ich musste einen Termin beim Einwohnermeldeamt vereinbaren. Ich brauchte meinen Ausweis und eine Bestätigung vom Vermieter. Der Termin dauerte nur zehn Minuten.","text_en":"I had to make an appointment at the residents'' registration office. I needed my ID and a confirmation from the landlord. The appointment only took ten minutes.","question":"What did the writer need from the landlord?","options":["A confirmation","A key","A contract"],"answer":0}'::jsonb, 'einen Termin vereinbaren is the standard phrase for booking an appointment.', 3201) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich brauche einen Termin.","en":"I need an appointment.","stress":"ich BRAU-che EI-nen ter-MIN","tip":"Termin is stressed on the last syllable, unlike English ''term''."}'::jsonb, 'Stress pattern: ich BRAU-che EI-nen ter-MIN', 3202) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich möchte einen Termin ___.","en":"I would like to make an appointment.","options":["vereinbaren","verlieren","verstehen"],"answer":0}'::jsonb, 'einen Termin vereinbaren means to make an appointment.', 3203) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","muss","mich","beim","Amt","anmelden"],"answer":["Ich","muss","mich","beim","Amt","anmelden"],"en":"I have to register at the office."}'::jsonb, 'sich anmelden is a separable reflexive verb; the prefix an- goes to the end.', 3204) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Termin","en":"the appointment"},{"de":"die Anmeldung","en":"the registration"},{"de":"der Ausweis","en":"the ID card"},{"de":"die Unterlagen","en":"the documents"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3205) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Bringen Sie bitte Ihren ___ mit.","en":"Please bring your ID with you.","options":["Ausweis","Auskunft","Anmeldung"],"answer":0}'::jsonb, 'der Ausweis is the identity card required at offices.', 3206) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You arrive at an office and need to explain you have a booked appointment.","question":"What do you say?","options":["Ich habe einen Termin um elf Uhr.","Ich will jetzt rein.","Termin, schnell!"],"answer":0}'::jsonb, 'State your appointment time clearly and politely.', 3207) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1fef55b1-46f7-5c81-a1f8-b54ec3f8652f'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie einen Behördengang, den Sie hatten oder haben müssen.', '{"prompt":"Beschreiben Sie einen Behördengang, den Sie hatten oder haben müssen.","hint":"Use: Ich musste einen Termin vereinbaren, ich brauchte …, der Termin dauerte …","sample":"Ich musste einen Termin beim Bürgeramt vereinbaren, weil ich umgezogen bin. Ich brauchte meinen Ausweis und eine Bestätigung vom Vermieter. Der Termin dauerte nur fünfzehn Minuten."}'::jsonb, 'Use the hint and compare your answer with the model.', 3208) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'renting-flat', 'A2', 'Renting a flat', 'Eine Wohnung mieten', 'housing', 'Discuss viewing and renting a flat with a landlord or agent.', 33) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wohnungsbesichtigung', '{"title":"Wohnungsbesichtigung","lines":[{"speaker":"Vermieterin","de":"Die Wohnung hat zwei Zimmer und eine kleine Küche.","en":"The flat has two rooms and a small kitchen."},{"speaker":"Frau Ahmadi","de":"Wie hoch ist die Kaltmiete?","en":"How much is the base rent?"},{"speaker":"Vermieterin","de":"Sechshundert Euro, plus Nebenkosten.","en":"Six hundred euros, plus additional costs."},{"speaker":"Frau Ahmadi","de":"Und ab wann ist sie frei?","en":"And from when is it available?"}],"question":"What is the Kaltmiete for the flat?","options":["600 euros","700 euros","500 euros"],"answer":0}'::jsonb, 'die Kaltmiete is the base rent without utilities; Nebenkosten are extra costs.', 3300) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meine neue Wohnung', '{"title":"Meine neue Wohnung","text_de":"Ich habe endlich eine Wohnung gefunden. Sie kostet vierhundertfünfzig Euro Kaltmiete plus Nebenkosten. Ich musste eine Kaution von zwei Monatsmieten bezahlen.","text_en":"I finally found a flat. It costs four hundred fifty euros base rent plus additional costs. I had to pay a deposit of two months'' rent.","question":"How much deposit did the writer pay?","options":["Two months'' rent","One month''s rent","No deposit"],"answer":0}'::jsonb, 'die Kaution is a security deposit, usually two to three months'' rent.', 3301) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Wie hoch ist die Miete?","en":"How much is the rent?","stress":"wie HOCH ist die MIE-te","tip":"The ie in Miete is a long i sound."}'::jsonb, 'Stress pattern: wie HOCH ist die MIE-te', 3302) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Die ___ kostet sechshundert Euro im Monat.","en":"The (base) rent costs six hundred euros a month.","options":["Kaltmiete","Kaution","Anmeldung"],"answer":0}'::jsonb, 'die Kaltmiete refers to rent without utility costs.', 3303) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Die","Wohnung","ist","ab","Januar","frei"],"answer":["Die","Wohnung","ist","ab","Januar","frei"],"en":"The flat is available from January."}'::jsonb, 'ab + month indicates the starting availability date.', 3304) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Miete","en":"the rent"},{"de":"die Kaution","en":"the deposit"},{"de":"die Nebenkosten","en":"the additional costs"},{"de":"der Vermieter","en":"the landlord"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3305) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich muss eine ___ von zwei Monatsmieten zahlen.","en":"I have to pay a deposit of two months'' rent.","options":["Kaution","Miete","Nebenkosten"],"answer":0}'::jsonb, 'die Kaution is the security deposit paid before moving in.', 3306) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are viewing a flat and want to ask when it becomes available.","question":"What do you ask?","options":["Ab wann ist die Wohnung frei?","Wie ist die Wohnung frei?","Wann Wohnung frei?"],"answer":0}'::jsonb, 'Ab wann ist … frei? is the natural way to ask about availability.', 3307) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5eeaaf4b-9a54-5739-a3c4-6f33aaa89b5c'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie eine Wohnung, die Sie mieten möchten.', '{"prompt":"Beschreiben Sie eine Wohnung, die Sie mieten möchten.","hint":"Use: Die Wohnung hat …, Die Kaltmiete beträgt …, Ich brauche eine Kaution von …","sample":"Die Wohnung hat drei Zimmer und einen Balkon. Die Kaltmiete beträgt siebenhundert Euro plus Nebenkosten. Ich muss eine Kaution von zwei Monatsmieten bezahlen."}'::jsonb, 'Use the hint and compare your answer with the model.', 3308) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'banking-money', 'A2', 'Banking and money', 'Bank und Geld', 'daily-life', 'Open a bank account and handle basic banking vocabulary.', 34) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Ein Konto eröffnen', '{"title":"Ein Konto eröffnen","lines":[{"speaker":"Bankberater","de":"Möchten Sie ein Girokonto eröffnen?","en":"Would you like to open a checking account?"},{"speaker":"Frau Sato","de":"Ja, ich brauche es für mein Gehalt.","en":"Yes, I need it for my salary."},{"speaker":"Bankberater","de":"Haben Sie Ihren Ausweis und eine Meldebescheinigung?","en":"Do you have your ID and a registration certificate?"},{"speaker":"Frau Sato","de":"Ja, hier bitte.","en":"Yes, here you go."}],"question":"Why does Frau Sato want a bank account?","options":["For her salary","For savings only","For a loan"],"answer":0}'::jsonb, 'ein Girokonto is the standard everyday checking account in Germany.', 3400) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meine Bank', '{"title":"Meine Bank","text_de":"Ich habe ein Konto bei einer Onlinebank. Meine Miete wird automatisch abgebucht. Wenn ich Geld brauche, hebe ich es am Automaten ab.","text_en":"I have an account with an online bank. My rent is automatically debited. When I need money, I withdraw it at the ATM.","question":"How does the writer pay rent?","options":["Automatic debit","Cash","Cheque"],"answer":0}'::jsonb, 'abbuchen means to debit automatically; abheben means to withdraw cash.', 3401) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich möchte Geld abheben.","en":"I would like to withdraw money.","stress":"ich MÖCH-te GELD AB-he-ben","tip":"abheben is a separable verb; ab- is stressed."}'::jsonb, 'Stress pattern: ich MÖCH-te GELD AB-he-ben', 3402) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich möchte ein Konto ___.","en":"I would like to open an account.","options":["eröffnen","abheben","bezahlen"],"answer":0}'::jsonb, 'ein Konto eröffnen means to open an account.', 3403) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","hebe","Geld","am","Automaten","ab"],"answer":["Ich","hebe","Geld","am","Automaten","ab"],"en":"I am withdrawing money at the ATM."}'::jsonb, 'The separable prefix ab- from abheben goes to the end.', 3404) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Konto","en":"the account"},{"de":"abheben","en":"to withdraw"},{"de":"überweisen","en":"to transfer"},{"de":"das Gehalt","en":"the salary"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3405) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Meine Miete wird automatisch ___.","en":"My rent is automatically debited.","options":["abgehoben","abgebucht","abgeschickt"],"answer":1}'::jsonb, 'abgebucht (from abbuchen) means automatically deducted.', 3406) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You need to ask a bank employee about opening an account.","question":"What is the appropriate question?","options":["Ich will ein Konto, sofort.","Könnten Sie mir helfen, ein Konto zu eröffnen?","Konto jetzt!"],"answer":1}'::jsonb, 'A polite question with Könnten Sie mir helfen is appropriate at a bank.', 3407) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('35648c88-1fbf-57fe-add9-2ad2882c2b7f'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie, wie Sie mit Geld und Bank umgehen.', '{"prompt":"Beschreiben Sie, wie Sie mit Geld und Bank umgehen.","hint":"Use: Ich habe ein Konto bei …, Ich überweise …, Ich hebe Geld ab, wenn …","sample":"Ich habe ein Konto bei einer großen Bank. Ich überweise meine Miete jeden Monat automatisch. Wenn ich Bargeld brauche, hebe ich es am Automaten ab."}'::jsonb, 'Use the hint and compare your answer with the model.', 3408) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'describing-people', 'A2', 'Describing people and character', 'Personen und Charakter beschreiben', 'people', 'Describe appearance and personality traits of people you know.', 35) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie ist dein neuer Kollege?', '{"title":"Wie ist dein neuer Kollege?","lines":[{"speaker":"Rosa","de":"Wie ist dein neuer Kollege?","en":"What is your new colleague like?"},{"speaker":"Felix","de":"Er ist sehr freundlich und hilfsbereit.","en":"He is very friendly and helpful."},{"speaker":"Rosa","de":"Und wie sieht er aus?","en":"And what does he look like?"},{"speaker":"Felix","de":"Er ist groß und hat kurze, braune Haare.","en":"He is tall and has short, brown hair."}],"question":"What is the new colleague''s personality like?","options":["Friendly and helpful","Shy and quiet","Rude"],"answer":0}'::jsonb, 'aussehen describes appearance; character adjectives describe personality.', 3500) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meine beste Freundin', '{"title":"Meine beste Freundin","text_de":"Meine beste Freundin heißt Clara. Sie ist klein und schlank und hat lockige Haare. Sie ist sehr geduldig und immer ehrlich zu mir.","text_en":"My best friend is called Clara. She is small and slim and has curly hair. She is very patient and always honest with me.","question":"What kind of hair does Clara have?","options":["Curly","Straight","Short"],"answer":0}'::jsonb, 'lockig means curly; ehrlich and geduldig describe character traits.', 3501) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Er ist sehr hilfsbereit.","en":"He is very helpful.","stress":"er ist sehr HILFS-be-reit","tip":"Hilfsbereit is a compound word stressed on Hilfs-."}'::jsonb, 'Stress pattern: er ist sehr HILFS-be-reit', 3502) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Sie hat lange, ___ Haare.","en":"She has long, blond hair.","options":["blonde","blond","blonder"],"answer":0}'::jsonb, 'Adjectives before a plural noun take the -e ending: blonde Haare.', 3503) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Meine","Schwester","ist","klein","und","sehr","lustig"],"answer":["Meine","Schwester","ist","klein","und","sehr","lustig"],"en":"My sister is small and very funny."}'::jsonb, 'Adjectives after sein describe the subject without endings.', 3504) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"freundlich","en":"friendly"},{"de":"geduldig","en":"patient"},{"de":"ehrlich","en":"honest"},{"de":"schlank","en":"slim"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3505) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Mein Bruder ist sehr ___.","en":"My brother is very honest.","options":["ehrlich","ehrliche","ehrlichen"],"answer":0}'::jsonb, 'After sein, adjectives take no ending.', 3506) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks you to describe someone you met at a party.","question":"Which is a natural description?","options":["Er ist nett und sehr witzig.","Er nett witzig ist.","Nett er ist."],"answer":0}'::jsonb, 'Simple sentence order: subject, verb, adjectives.', 3507) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('44aed786-9009-56a3-a7c7-1af4cded4a41'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie eine Person, die Sie gut kennen.', '{"prompt":"Beschreiben Sie eine Person, die Sie gut kennen.","hint":"Use: … ist …, … hat …, … sieht … aus.","sample":"Mein bester Freund heißt Tom. Er ist groß und hat kurze, dunkle Haare. Er ist sehr lustig und immer hilfsbereit."}'::jsonb, 'Use the hint and compare your answer with the model.', 3508) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'telling-story', 'A2', 'Telling a story', 'Eine Geschichte erzählen', 'narrative', 'Narrate a simple past event using connectors like zuerst, dann and danach.', 36) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Was ist passiert?', '{"title":"Was ist passiert?","lines":[{"speaker":"Nora","de":"Was ist gestern passiert?","en":"What happened yesterday?"},{"speaker":"Tobias","de":"Zuerst habe ich verschlafen. Dann habe ich den Bus verpasst.","en":"First I overslept. Then I missed the bus."},{"speaker":"Nora","de":"Oje! Und danach?","en":"Oh no! And after that?"},{"speaker":"Tobias","de":"Danach bin ich mit dem Taxi zur Arbeit gefahren.","en":"After that I went to work by taxi."}],"question":"How did Tobias get to work in the end?","options":["By taxi","By bus","On foot"],"answer":0}'::jsonb, 'zuerst, dann and danach help order events in a story.', 3600) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Ein verrückter Tag', '{"title":"Ein verrückter Tag","text_de":"Zuerst klingelte mein Wecker nicht. Dann fand ich meine Schlüssel nicht. Schließlich kam ich eine Stunde zu spät zur Arbeit.","text_en":"First my alarm clock did not ring. Then I could not find my keys. Finally I arrived an hour late for work.","question":"What was the final result of the story?","options":["Arriving late to work","Missing a meeting","Losing the keys forever"],"answer":0}'::jsonb, 'schließlich signals the final event in a sequence of a story.', 3601) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Zuerst, dann, danach, schließlich.","en":"First, then, after that, finally.","stress":"tsu-ERST, DANN, da-NACH, SCHLIESS-lich","tip":"These connectors are common signposts in spoken narratives."}'::jsonb, 'Stress pattern: tsu-ERST, DANN, da-NACH, SCHLIESS-lich', 3602) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ bin ich aufgestanden, dann habe ich gefrühstückt.","en":"First I got up, then I had breakfast.","options":["Zuerst","Schließlich","Nie"],"answer":0}'::jsonb, 'Zuerst introduces the first event in a sequence.', 3603) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Zuerst","sind","wir","spazieren","gegangen"],"answer":["Zuerst","sind","wir","spazieren","gegangen"],"en":"First we went for a walk."}'::jsonb, 'Time connector zuerst goes first, verb second.', 3604) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"zuerst","en":"first"},{"de":"dann","en":"then"},{"de":"danach","en":"after that"},{"de":"schließlich","en":"finally"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3605) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"___ hat es geregnet, deshalb kamen wir spät an.","en":"It rained, therefore we arrived late.","options":["Deshalb","Danach","Zuerst"],"answer":1}'::jsonb, 'Danach signals the event that follows chronologically.', 3606) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are telling a friend a funny story about your day and want it to flow logically.","question":"Which connectors help order the events?","options":["Zuerst, dann, danach, schließlich","Vielleicht, aber, oder","Und, oder, aber"],"answer":0}'::jsonb, 'Sequencing words help structure a narrative clearly.', 3607) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('71739b93-4963-56be-a8ff-6772c134b925'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Erzählen Sie eine kurze Geschichte von einem besonderen Tag.', '{"prompt":"Erzählen Sie eine kurze Geschichte von einem besonderen Tag.","hint":"Use: Zuerst …, Dann …, Danach …, Schließlich …","sample":"Zuerst bin ich früh aufgewacht. Dann habe ich mich mit Freunden getroffen. Danach sind wir ins Kino gegangen. Schließlich haben wir zusammen zu Abend gegessen."}'::jsonb, 'Use the hint and compare your answer with the model.', 3608) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'opinions-disagreement', 'A2', 'Opinions and disagreement', 'Meinungen äußern und widersprechen', 'conversation', 'Express your opinion politely and disagree in a respectful way.', 37) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Eine Diskussion', '{"title":"Eine Diskussion","lines":[{"speaker":"Hakan","de":"Ich finde, dass Homeoffice besser ist.","en":"I think that working from home is better."},{"speaker":"Ines","de":"Das stimmt nicht ganz. Im Büro arbeitet man produktiver.","en":"That''s not quite true. You work more productively in the office."},{"speaker":"Hakan","de":"Da bin ich anderer Meinung.","en":"I disagree with that."}],"question":"What does Hakan think is better?","options":["Working from home","Working in the office","A mix of both"],"answer":0}'::jsonb, 'Ich bin anderer Meinung is a polite way to disagree.', 3700) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meinungen zum Handy in der Schule', '{"title":"Meinungen zum Handy in der Schule","text_de":"Manche Leute meinen, dass Handys in der Schule verboten sein sollten. Andere finden, dass man sie zum Lernen nutzen kann. Ich persönlich glaube, dass es auf die Situation ankommt.","text_en":"Some people think that phones should be banned in school. Others think you can use them for learning. Personally, I believe it depends on the situation.","question":"What does the writer personally believe?","options":["It depends on the situation","Phones should be banned","Phones are always useful"],"answer":0}'::jsonb, 'meinen and glauben introduce personal opinions.', 3701) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich bin anderer Meinung.","en":"I disagree.","stress":"ich bin AN-de-rer MEI-nung","tip":"Meinung stresses the first syllable, MEI-."}'::jsonb, 'Stress pattern: ich bin AN-de-rer MEI-nung', 3702) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich ___, dass das eine gute Idee ist.","en":"I think that this is a good idea.","options":["finde","find","findet"],"answer":0}'::jsonb, 'ich finde is the first-person form used to give an opinion.', 3703) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Meiner","Meinung","nach","ist","das","richtig"],"answer":["Meiner","Meinung","nach","ist","das","richtig"],"en":"In my opinion, that is right."}'::jsonb, 'Meiner Meinung nach is a fixed phrase introducing an opinion.', 3704) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Meinung","en":"the opinion"},{"de":"zustimmen","en":"to agree"},{"de":"widersprechen","en":"to disagree"},{"de":"meiner Meinung nach","en":"in my opinion"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3705) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Da bin ich ___ Meinung.","en":"I am of a different opinion there.","options":["anderer","anderen","anders"],"answer":0}'::jsonb, 'anderer Meinung sein means to disagree.', 3706) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A colleague states an opinion you strongly disagree with in a meeting.","question":"What is a polite way to disagree?","options":["Das ist falsch!","Ich sehe das anders.","Du hast keine Ahnung."],"answer":1}'::jsonb, 'Ich sehe das anders is a softer, more polite way to disagree.', 3707) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('25b7e1da-8c03-58a8-a9a5-32eba4d67aa0'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Äußern Sie Ihre Meinung zu einem aktuellen Thema.', '{"prompt":"Äußern Sie Ihre Meinung zu einem aktuellen Thema.","hint":"Use: Ich finde, dass …, Meiner Meinung nach …, Ich bin anderer Meinung, weil …","sample":"Ich finde, dass Homeoffice viele Vorteile hat. Meiner Meinung nach spart man Zeit und Geld. Manche sind anderer Meinung, weil ihnen der Kontakt zu Kollegen fehlt."}'::jsonb, 'Use the hint and compare your answer with the model.', 3708) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'news-media', 'A2', 'News and media', 'Nachrichten und Medien', 'media', 'Talk about how you follow the news and different media sources.', 38) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie informierst du dich?', '{"title":"Wie informierst du dich?","lines":[{"speaker":"Petra","de":"Wie informierst du dich über Nachrichten?","en":"How do you keep up with the news?"},{"speaker":"Ali","de":"Ich lese meistens eine Nachrichten-App.","en":"I mostly read a news app."},{"speaker":"Petra","de":"Ich schaue lieber die Tagesschau im Fernsehen.","en":"I prefer to watch the Tagesschau on TV."}],"question":"How does Ali follow the news?","options":["Via a news app","Newspaper","Radio"],"answer":0}'::jsonb, 'sich informieren über means to keep informed about something.', 3800) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Nachrichten heute', '{"title":"Nachrichten heute","text_de":"Früher haben die Menschen nur Zeitung gelesen. Heute nutzen viele das Internet und soziale Medien. Manche vertrauen den Nachrichten im Internet nicht so sehr.","text_en":"In the past people only read newspapers. Today many use the internet and social media. Some do not trust the news on the internet as much.","question":"What did people mainly use in the past?","options":["Newspapers","Radio","Television"],"answer":0}'::jsonb, 'vertrauen + dative expresses trust: den Nachrichten vertrauen.', 3801) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich lese die Nachrichten online.","en":"I read the news online.","stress":"ich LE-se die NACH-rich-ten ON-lein","tip":"Nachrichten stresses the first syllable Nach-."}'::jsonb, 'Stress pattern: ich LE-se die NACH-rich-ten ON-lein', 3802) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich ___ mich jeden Tag über die Nachrichten.","en":"I inform myself about the news every day.","options":["informiere","informieren","informiert"],"answer":0}'::jsonb, 'sich informieren conjugates like a regular reflexive verb.', 3803) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","informiere","mich","über","das","Internet"],"answer":["Ich","informiere","mich","über","das","Internet"],"en":"I inform myself via the internet."}'::jsonb, 'The reflexive pronoun mich comes right after the verb.', 3804) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Nachrichten","en":"the news"},{"de":"die Zeitung","en":"the newspaper"},{"de":"vertrauen","en":"to trust"},{"de":"sich informieren","en":"to inform oneself"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3805) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Viele Leute vertrauen ___ Zeitungen nicht mehr.","en":"Many people no longer trust newspapers.","options":["die","den","der"],"answer":1}'::jsonb, 'vertrauen takes the dative: den Zeitungen.', 3806) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A friend asks where you get reliable information from.","question":"What is a natural response?","options":["Ich informiere mich über seriöse Nachrichtenseiten.","Ich lese nichts.","Nachrichten sind langweilig."],"answer":0}'::jsonb, 'seriös means reliable/credible, an important word when discussing media.', 3807) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('784f6db7-58fc-575c-ab54-ae65410ce857'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wie informieren Sie sich über aktuelle Ereignisse?', '{"prompt":"Wie informieren Sie sich über aktuelle Ereignisse?","hint":"Use: Ich informiere mich über …, Ich lese/schaue …, Ich vertraue …","sample":"Ich informiere mich meistens über eine Nachrichten-App. Am Abend schaue ich auch die Nachrichten im Fernsehen. Ich vertraue vor allem seriösen Zeitungen."}'::jsonb, 'Use the hint and compare your answer with the model.', 3808) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'culture-traditions', 'A2', 'Culture and traditions', 'Kultur und Traditionen', 'culture', 'Discuss German festivals and traditions and compare them with your own.', 39) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Weihnachtsmarkt', '{"title":"Weihnachtsmarkt","lines":[{"speaker":"Yara","de":"Warst du schon auf dem Weihnachtsmarkt?","en":"Have you already been to the Christmas market?"},{"speaker":"Finn","de":"Ja, ich habe Glühwein getrunken und Lebkuchen gegessen.","en":"Yes, I drank mulled wine and ate gingerbread."},{"speaker":"Yara","de":"In meinem Land haben wir andere Traditionen zu Weihnachten.","en":"In my country we have other traditions for Christmas."}],"question":"What did Finn eat at the Christmas market?","options":["Lebkuchen","Bratwurst","Kuchen"],"answer":0}'::jsonb, 'der Weihnachtsmarkt is a popular German winter tradition.', 3900) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Deutsche Feste', '{"title":"Deutsche Feste","text_de":"In Deutschland feiert man im Oktober das Oktoberfest in München. Zu Ostern bemalen viele Familien Eier. An Weihnachten schmückt man einen Tannenbaum.","text_en":"In Germany, people celebrate the Oktoberfest in Munich in October. At Easter, many families paint eggs. At Christmas, people decorate a fir tree.","question":"What do people do at Easter in Germany?","options":["Paint eggs","Light candles","Bake bread"],"answer":0}'::jsonb, 'bemalen means to paint/decorate something.', 3901) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Wir feiern Weihnachten zusammen.","en":"We celebrate Christmas together.","stress":"wir FEI-ern WEIH-nach-ten zu-SAM-men","tip":"The ei in feiern and Weihnachten sounds like English ''eye''."}'::jsonb, 'Stress pattern: wir FEI-ern WEIH-nach-ten zu-SAM-men', 3902) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"In Deutschland ___ man im Herbst das Oktoberfest.","en":"In Germany, people celebrate the Oktoberfest in autumn.","options":["feiert","feiern","gefeiert"],"answer":0}'::jsonb, 'man takes the third-person singular verb form: man feiert.', 3903) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["An","Weihnachten","schmücken","wir","einen","Tannenbaum"],"answer":["An","Weihnachten","schmücken","wir","einen","Tannenbaum"],"en":"At Christmas we decorate a fir tree."}'::jsonb, 'An Weihnachten is the fixed expression for ''at Christmas''.', 3904) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Fest","en":"the festival"},{"de":"feiern","en":"to celebrate"},{"de":"die Tradition","en":"the tradition"},{"de":"schmücken","en":"to decorate"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 3905) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Zu Ostern ___ viele Familien Eier.","en":"At Easter many families paint eggs.","options":["bemalen","bemalt","bemale"],"answer":0}'::jsonb, 'viele Familien is plural, so the verb takes the plural ending -en.', 3906) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A German friend invites you to a traditional festival and asks about your own traditions.","question":"How could you respond?","options":["In meinem Land feiern wir das anders.","Ich habe keine Traditionen.","Das interessiert mich nicht."],"answer":0}'::jsonb, 'Sharing your own cultural traditions is a natural, friendly response.', 3907) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('20a3c9c9-4c2d-5984-a8d8-f96e80a19df4'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie ein Fest oder eine Tradition aus Ihrem Land.', '{"prompt":"Beschreiben Sie ein Fest oder eine Tradition aus Ihrem Land.","hint":"Use: Bei uns feiern wir …, Wir essen/trinken …, Diese Tradition bedeutet …","sample":"Bei uns feiern wir im Frühling ein großes Fest. Wir essen traditionelles Gebäck und treffen die ganze Familie. Diese Tradition bedeutet für uns viel."}'::jsonb, 'Use the hint and compare your answer with the model.', 3908) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'a2-recap', 'A2', 'A2 recap', 'A2 Wiederholung', 'review', 'Review key A2 grammar and vocabulary through everyday situations.', 40) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Ein Jahr in Deutschland', '{"title":"Ein Jahr in Deutschland","lines":[{"speaker":"Lehrerin","de":"Wie war dein erstes Jahr in Deutschland?","en":"How was your first year in Germany?"},{"speaker":"Diego","de":"Am Anfang war es schwer, weil ich wenig Deutsch sprach.","en":"At the beginning it was hard, because I spoke little German."},{"speaker":"Lehrerin","de":"Und jetzt?","en":"And now?"},{"speaker":"Diego","de":"Jetzt fühle ich mich viel sicherer und werde bald die B1-Prüfung machen.","en":"Now I feel much more confident and will soon take the B1 exam."}],"question":"What will Diego do soon?","options":["Take the B1 exam","Move back home","Start university"],"answer":0}'::jsonb, 'This dialogue combines Präteritum, reflexive verbs and the future with werden.', 4000) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Rückblick auf mein Deutschlernen', '{"title":"Rückblick auf mein Deutschlernen","text_de":"Als ich nach Deutschland kam, konnte ich nur wenige Wörter. Ich habe viel gelernt, weil ich jeden Tag geübt habe. Bald werde ich die nächste Prüfung machen, weil ich mich gut vorbereitet fühle.","text_en":"When I came to Germany, I could only speak a few words. I have learned a lot because I practised every day. Soon I will take the next exam because I feel well prepared.","question":"Why has the writer learned a lot?","options":["Practised every day","Took a course abroad","Watched films only"],"answer":0}'::jsonb, 'This passage combines als, weil, Perfekt and the future with werden.', 4001) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich habe viel gelernt und fühle mich sicherer.","en":"I have learned a lot and feel more confident.","stress":"ich HA-be FIEL ge-LERNT und FÜH-le mich SI-che-rer","tip":"Practise linking clauses smoothly without pausing too much."}'::jsonb, 'Stress pattern: ich HA-be FIEL ge-LERNT und FÜH-le mich SI-che-rer', 4002) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Als ich ankam, ___ ich kein Deutsch.","en":"When I arrived, I spoke no German.","options":["sprach","spreche","gesprochen"],"answer":0}'::jsonb, 'als + Präteritum describes a single past situation.', 4003) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","werde","mich","gut","vorbereiten"],"answer":["Ich","werde","mich","gut","vorbereiten"],"en":"I will prepare myself well."}'::jsonb, 'sich vorbereiten combines a reflexive verb with the future werden construction.', 4004) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"sich vorbereiten","en":"to prepare oneself"},{"de":"die Prüfung","en":"the exam"},{"de":"sicherer","en":"more confident/secure"},{"de":"üben","en":"to practise"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 4005) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich werde die Prüfung bestehen, ___ ich viel geübt habe.","en":"I will pass the exam because I have practised a lot.","options":["weil","wenn","aber"],"answer":0}'::jsonb, 'weil introduces the reason, with the verb at the end.', 4006) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A classmate asks how your German learning journey has been so far.","question":"Which response best summarises progress using A2 grammar?","options":["Am Anfang war es schwer, aber ich habe viel geübt und werde bald die Prüfung machen.","Deutsch ist schwer.","Ich weiß nicht."],"answer":0}'::jsonb, 'A rich answer uses Präteritum, Perfekt and the future together.', 4007) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f7762ce5-bb53-5902-ad40-e71ad7e5f501'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie einen kurzen Rückblick auf Ihr Deutschlernen mit verschiedenen Zeitformen.', '{"prompt":"Schreiben Sie einen kurzen Rückblick auf Ihr Deutschlernen mit verschiedenen Zeitformen.","hint":"Use: Als ich anfing, …; Ich habe …; Jetzt werde ich …","sample":"Als ich anfing, Deutsch zu lernen, konnte ich nur wenige Sätze. Ich habe viel geübt und mit anderen Lernenden gesprochen. Jetzt fühle ich mich sicherer und werde bald die B1-Prüfung machen."}'::jsonb, 'Use the hint and compare your answer with the model.', 4008) ON CONFLICT (id) DO NOTHING;
